"""Original Russian editorial copy; primary sources reviewed 2026-11-15."""
STORIES = [
 dict(id='light', theme='Фактура', title='Почему одни колготки ловят свет, а другие его смягчают', short='Блеск и матовость', image='cdr-gloss', description='Учимся читать блики, прозрачность и цвет на реальной фотографии — и понимаем, чего она не показывает.', sections=[
 ('look','Сначала посмотрите на свет',[
 'У блестящих колготок взгляд обычно цепляется за светлую дорожку вдоль ноги. На матовой поверхности переход выглядит более рассеянным. Но фотография показывает совместную работу ткани, формы тела и освещения: узкий источник света, большое окно и вспышка дают разные рисунки бликов. Один и тот же предмет может выглядеть спокойнее в комнате и заметно ярче в студии.',
 'В каталоге Cecilia de Rafael рядом существуют прозрачные модели и изделия с выраженным блеском, например Eterno Super Lucido 10. Название помогает найти нужное визуальное направление, но не заменяет изображений в нескольких ракурсах. Сравните переднюю сторону голени, участок у колена и боковую линию: натяжение и угол к свету здесь различаются.']),
 ('thread','Что говорит число DEN',[
 'DEN описывает линейную плотность нити: массу девяти километров в граммах. Это не процент прозрачности и не шкала блеска. На результат также влияют вязка, цвет, состав и растяжение полотна. Поэтому две модели с одинаковым числом на упаковке могут заметно отличаться на ноге.',
 'Полезно разделить три вопроса: насколько видна кожа, насколько выражен блик и насколько ровным кажется оттенок. Они связаны, но не совпадают. Блестящий эффект бывает у тонких и более плотных изделий; видимая прозрачность не доказывает, что вещь будет прохладной или тонкой на ощупь.']),
 ('compare','Как сравнивать каталожные кадры',[
 'Начните с похожих ракурсов и фона. Затем найдите второй снимок каждой модели: общий план показывает силуэт, крупный — край пояса, мысок и структуру. У Calzedonia блестящие и фантазийные модели вынесены в отдельные товарные варианты; у Philippe Matignon есть раздел тонких и очень тонких колготок. Это удобные маршруты поиска, а не единый стандарт прозрачности.',
 'Не сравнивайте точный оттенок по двум разным экранам. Баланс белого, обработка фотографии и тон кожи меняют восприятие. Если цвет важен для конкретной обуви или одежды, каталожный кадр помогает составить короткий список, а окончательный выбор требует проверки самой вещи.']),
 ('practice','Небольшое упражнение для глаза',[
 'Откройте «Под лупой» и увеличьте фотографию на один шаг. Найдите светлую полосу, затем рассмотрите соседний участок в тени. Это объясняет блеск на данном снимке лучше, чем попытка вычислить его по числу DEN. Вернитесь к общему плану: хорошая деталь не должна заслонять весь силуэт.',
 'Для своей подборки сохраните один матовый и один блестящий образ с похожим цветом. Подпишите для себя, что именно привлекает: ровный тон, мягкая прозрачность или контрастный блик. Так выбор становится конкретным и не зависит только от слова «красивые».'])],
 sources=[('https://ceciliaderafael.com/en','Cecilia de Rafael: ассортимент и визуальная подача'),('https://www.calzedonia.com/us/women/tights_and_stockings/','Calzedonia: колготки и чулки'),('https://www.philippematignon.it/','Philippe Matignon: разделы тонких колготок')],
 question='У двух моделей 20 DEN. Будет ли у них одинаковый блеск?', answers=['Да, DEN задаёт блеск','Нет, одного DEN недостаточно','Только у чёрных'], correct=1, feedback='DEN относится к нити. Внешний вид зависит также от конструкции полотна, материала, натяжения и освещения.', next=('textures.html','Сравнить фактуры под лупой'), related=['patterns','product-card']),
 dict(id='patterns',theme='Стиль',title='Рисунок, который меняет весь образ',short='Горох, кружево и геометрия',image='noq-lace',description='Масштаб узора, фон и расстояние: три способа внимательнее рассмотреть фантазийные колготки.',sections=[
 ('scale','Масштаб важнее названия',[
 'Слово «кружево» объединяет очень разные рисунки: мелкую сетку с цветочными мотивами, крупные ветви, плотный орнамент. Издалека мелкий рисунок может сливаться в тон, а крупный оставаться самостоятельным акцентом. Поэтому перед покупкой полезно посмотреть на изображение целиком и только потом увеличивать детали.',
 'В NOQ навигация разделяет горох, цветы, геометрию, сердца, сетку и имитацию чулок. Такой подход помогает описать предпочтение точнее, чем общее слово «фантазийные». У модели Secret один цветочный мотив показан в нескольких оттенках: на чёрном и коричневом фоне его характер воспринимается по-разному.']),
 ('context','Один узор — несколько сочетаний',[
 'Удобная отправная точка — выбрать, чему вы отдаёте главную роль. Если колготки должны быть заметной частью образа, спокойная крупная поверхность юбки или платья оставляет рисунку пространство. Если интересен сложный комплект, можно повторить в одежде один цвет или направление линии. Это приём композиции, а не обязательный дресс-код.',
 'Посмотрите на границу между обувью и ногой. Высота голенища, ремешок и цвет обуви влияют на то, как читается рисунок в нижней части силуэта. Каталожный комплект — один из вариантов стилизации; он не означает, что модель требует именно таких туфель или длины юбки.']),
 ('construction','Узор не рассказывает всю конструкцию',[
 'Имитация чулок может быть частью цельных колготок: тёмная нижняя зона и более прозрачный верх создают нужную композицию без отдельной подвязки. И наоборот, внешний вид верхнего края на фотографии не всегда позволяет отличить чулки от колготок. Ищите название типа изделия и снимок целиком.',
 'При примерке рисунок растягивается вместе с полотном. Особенно заметны изменения крупных геометрических ячеек и полос. Сверяйтесь с размерной сеткой производителя и оценивайте комфорт, а не пытайтесь сохранить вид узора из студийного кадра ценой слишком тесной посадки.']),
 ('collection','Соберите маленькую визуальную коллекцию',[
 'Выберите в галерее три изображения: мелкий мотив, крупный орнамент и однотонную модель. Сохраните их кнопкой под фотографией. Затем откройте только свою подборку и сравните общий силуэт. Контраст между вариантами помогает понять собственный вкус лучше, чем десятки почти одинаковых кадров.',
 'В просмотре деталей можно приблизить кружево Secret и блестящую модель Calzedonia. У них разные свет и поза, поэтому это исследование рисунка, а не лабораторное сравнение материалов. Авторство каждой фотографии указано рядом с изображением.'])],sources=[('https://noq.com.pl/kategoria-produktu/kobieta/rajstopy/','NOQ: навигация по видам рисунка'),('https://noq.com.pl/produkt/rajstopy-damskie-secret-z-delikatnym-wzorem-kwiatow/','NOQ: Secret в нескольких цветах'),('https://www.calzedonia.com/us/women/tights_and_stockings/','Calzedonia: фантазийные модели')],question='Имитация чулок обязательно означает два отдельных изделия?',answers=['Да, это всегда чулки','Нет, это может быть рисунок колготок','Зависит только от цвета'],correct=1,feedback='Рисунок и конструкция — разные признаки. Проверьте тип изделия в карточке и фотографию верхней части.',next=('lookbook.html?filter=pattern','Собрать подборку рисунков'),related=['light','construction']),
 dict(id='construction',theme='Устройство',title='Колготки заканчиваются не всегда у пальцев',short='Стопа, пояс, шортики',image='spanx-hosiery',description='Footless, shorty, высокая посадка и бесшовные зоны: разбираем слова, за которыми скрывается конструкция.',sections=[
 ('foot','Начните с нижнего края',[
 'Полная стопа, открытые пальцы и вариант без стопы решают разные задачи. У footless изделие заканчивается выше стопы; у модели с открытым мыском часть стопы сохраняется. Это влияет на сочетание с обувью, видимость края и ощущение при движении. По одной фотографии ноги в туфле различие бывает незаметно.',
 'В разделе Hosiery у SPANX есть названия Footless Sheers, Shorty Tights и Tights. Они показывают, насколько полезно сначала выбрать конструкцию и только потом сравнивать цвет или прозрачность. Надпись shorty относится к короткой верхней зоне конкретной модели; точный крой нужно проверять по описанию и снимкам изделия.']),
 ('waist','Посадка и коррекция — разные параметры',[
 'Высокий пояс описывает положение верхнего края. Корректирующий эффект — заявленное свойство конкретной конструкции. Одно не следует автоматически из другого: высокая посадка может нравиться просто потому, что лучше сочетается с вашей одеждой или меньше открывает поясницу.',
 'Проверяйте вещь сидя, стоя и в наклоне. Пояс не должен требовать постоянного поправления или причинять боль. Более сильное давление не является доказательством лучшей посадки. Компрессионные медицинские изделия — отдельная категория; обычная надпись shaping не заменяет медицинское назначение.']),
 ('seams','Что означает «без швов»',[
 'У Philippe Matignon есть отдельный раздел изделий без швов. Но даже такое название нужно читать вместе с конструкцией: речь может идти об отсутствии центрального шва, определённой технологии вязания или отдельной зоне. Мысок, пояс и соединения деталей требуют самостоятельной проверки.',
 'На увеличенной фотографии ищите переход между верхом и ногой, обработку мыска и край пояса. Это не повод оценивать качество только по числу видимых линий: удачно расположенный плоский шов может оказаться комфортнее конструкции, которая выглядит «невидимой» в каталоге.']),
 ('wardrobe','Проверка под свою одежду',[
 'Составьте короткий сценарий: какая обувь, где заканчивается юбка или брюки, насколько облегает верхний слой, сколько времени вы будете сидеть или двигаться. Такая последовательность сужает выбор гораздо быстрее, чем поиск универсально «лучших» колготок.',
 'Если нужен самостоятельный предмет для тренировки, перейдите к легинсам и тайтсам: там важны непрозрачность при движении и устойчивость пояса. Прозрачные footless-колготки и спортивные легинсы могут быть похожи нижним краем, но не становятся из-за этого взаимозаменяемыми.'])],sources=[('https://spanx.com/en-gb/collections/hosiery','SPANX: типы чулочных изделий'),('https://spanx.com/en-gb/products/spanxshape-original-spanx-high-waisted-footless-sheers','SPANX: High-Waisted Footless Sheers'),('https://www.philippematignon.it/collections/senza-cuciture-donna','Philippe Matignon: изделия без швов')],question='High-waisted и footless описывают одно и то же?',answers=['Да, высокий пояс','Нет: первое о поясе, второе о стопе','Да, степень коррекции'],correct=1,feedback='Высота пояса, наличие стопы и корректирующие свойства — отдельные характеристики.',next=('guide.html#anatomy','Разобрать конструкцию'),related=['product-card','patterns']),
 dict(id='product-card',theme='Практика',title='Как прочитать карточку колготок и не потеряться в обещаниях',short='Пять вопросов к одной паре',image='pm-sheer',description='Состав, размер, DEN, конструкция и уход. Превращаем красивую фотографию в осмысленный выбор.',sections=[
 ('type','1. Что именно продаётся',[
 'Начните с типа изделия: колготки, чулки, гольфы, легинсы или модель без стопы. Затем уточните пояс, верхнюю часть, мысок и наличие ластовицы. Фотография показывает образ, но не всегда все технические зоны. У SPANX конструкция часто вынесена прямо в название; в каталоге Calzedonia первый уровень выбора разделяет основные типы чулочных изделий.',
 'Сохранённая картинка без названия модели быстро теряет практическую пользу. Рядом полезно оставить источник: там можно проверить размерную сетку, цветовой код и рекомендации производителя. Ссылки в ТОНКО ведут именно к публикациям брендов, когда они установлены.']),
 ('material','2–3. Из чего сделано и как выглядит',[
 'Процентный состав сообщает о волокнах. Полиамид и эластан выполняют разные роли, но одна доля эластана не предсказывает мягкость, срок службы или степень утяжки. Эти свойства зависят также от нити, вязки, конструкции и посадки. Если в карточке не хватает данных, точнее признать это, чем делать вывод по рекламному прилагательному.',
 'DEN — ещё одна характеристика нити, а не готовая оценка изделия. Сравните прозрачность на общем плане, рассмотрите матовость или блеск и проверьте цвет. У Gabriella встречаются модели с эффектом прозрачности в зимней линейке Arctic: внешнее впечатление само по себе не сообщает ни состав, ни устройство слоёв.']),
 ('size','4. Подходит ли размер',[
 'Размерные обозначения не универсальны. Пользуйтесь таблицей конкретного производителя и сравнивайте те параметры, которые в ней указаны. Рост, обхваты и особенности конструкции могут быть важнее привычной буквы на другой одежде. Не стоит выбирать заведомо маленький размер ради большего «эффекта».',
 'На примерке обратите внимание на длину ноги, положение шаговой зоны, натяжение в колене и устойчивость пояса. Если изделие постоянно сползает, причина может быть в размере или несовпадении кроя с фигурой. Это не исправляется автоматически повышением DEN.']),
 ('claims','5. Как ухаживать и что подтверждено',[
 'Ищите инструкцию по стирке, сушке и надеванию. Затем отделите визуальное описание от обещаний эффекта. «Блестящие» можно оценить на фото; утверждение о здоровье, антицеллюлитном действии или лечебной компрессии требует совсем другого подтверждения. Фильтр интернет-магазина не является клиническим исследованием.',
 'В мастерской выбора можно собрать собственные приоритеты, пройти короткую проверку знаний и оценить стоимость одной носки. Это ориентиры для сравнения, а не гарантия срока службы. Лучше выбрать несколько подходящих моделей по понятным критериям, чем искать одно рекламное слово, которое решит всё.'])],sources=[('https://www.calzedonia.com/us/women/tights_and_stockings/','Calzedonia: категории и рекомендации'),('https://spanx.com/en-gb/collections/hosiery','SPANX: конструкция и фильтры'),('https://www.gabriella.pl/','Gabriella: ассортимент Arctic'),('https://noq.com.pl/kategoria-produktu/kobieta/rajstopy/','NOQ: свойства и фильтры каталога')],question='Какая информация лучше помогает выбрать размер?',answers=['Название коллекции','Таблица конкретного производителя','Только число DEN'],correct=1,feedback='Сначала таблица производителя и ваши параметры, затем проверка посадки. DEN не определяет размер.',next=('guide.html','Собрать критерии своей пары'),related=['construction','light']),
 dict(id='making',theme='Индустрия',title='За красивым кадром: кто и как выпускает колготки',short='От фабрики до витрины',image='swedish-factory',description='Три разных масштаба бизнеса: семейное производство, группа брендов и компания с длинным архивом.',sections=[
 ('family','Gabriella: семейная история и производство',[
 'В разделе «О нас» Gabriella указывает 1996 год основания и описывает себя как семейную компанию. Производственная площадка находится в Лодзи, на улице Brukowa. На той же странице компания рассказывает о машинах, сотрудниках и объёмах выпуска. Такие числа полезны как собственная презентация предприятия, но не становятся независимым аудитом только потому, что опубликованы на официальном сайте.',
 'Для читателя важнее понять цепочку: разработка модели, подбор нитей, вязание, отделка, проверка и упаковка. У разных изделий порядок и содержание операций могут различаться. В ТОНКО эта цепочка разобрана отдельно, а фото оборудования подписано по реальному источнику, без приписывания одной фабрики другому бренду.']),
 ('group','Golden Lady и OMSA: марка не равна группе',[
 'Golden Lady Company объединяет несколько марок. Корпоративная страница Golden Lady описывает ассортимент колготок, чулок и других изделий, а также работу с крупной розницей и оптовыми каналами. Это один способ масштабировать доступность: покупатель встречает товар в разных торговых форматах, а не только в отдельном фирменном бутике.',
 'OMSA входит в группу с 1992 года. Это дата перехода в состав Golden Lady, а не рождения самой марки. У брендов внутри одной группы могут сохраняться собственные названия, визуальные образы и позиции в ассортименте. Поэтому карточку марки и историю владельца полезно читать отдельно.']),
 ('continuity','FALKE: преемственность через архив',[
 'Официальная хронология FALKE начинается 8 мая 1895 года с мастерской Франца Фальке-Роэна. В 1951 году управление перешло к Паулю и Францу-Отто; с 1990 года компания рассказывает о четвёртом поколении семьи. Архивные фотографии помогают увидеть людей за датами, но сами по себе не доказывают характеристики современных изделий.',
 'Длинная история — это материал для изучения решений, а не автоматический знак превосходства. Важно различать преемственность, расширение ассортимента, технологические изменения и рекламный язык. Убедительная история компании связывает событие с источником и не превращает каждое десятилетие в легенду.']),
 ('economics','Что остаётся за кадром',[
 'Красивая съёмка — только одна часть работы. Есть размерный и цветовой запас, брак, возвраты, доставка, хранение и сезонность. Цена на полке не равна прибыли с пары. Если товар продаётся через посредников, условия цепочки добавляют ещё один уровень расчёта.',
 'В разделе «Индустрия» можно изменить исходные числа в учебном расчёте и увидеть, как меняется остаток после переменных расходов. Это не оценка доходности Gabriella, FALKE или Golden Lady: для такого вывода нужны их реальные сопоставимые данные. Здесь расчёт помогает понять логику, а истории показывают разные способы организовать бизнес.'])],sources=[('https://www.gabriella.pl/pages/o-nas','Gabriella: история и производственная площадка'),('https://www.goldenladycompany.com/en/brand/golden-lady','Golden Lady Company: марка Golden Lady'),('https://www.goldenladycompany.com/en/brand/omsa','Golden Lady Company: марка OMSA'),('https://www.falke.com/uk_en/about-us/history/','FALKE: поколения и хронология')],question='1992 год на корпоративной странице OMSA — это…',answers=['Основание марки','Вхождение в Golden Lady Company','Изобретение нейлона'],correct=1,feedback='1992 — дата вхождения OMSA в группу. Даты марки и её владельца нужно различать.',next=('business.html','Исследовать производство и экономику'),related=['archive','product-card']),
 dict(id='archive',theme='История',title='Как читать историю бренда: даты, люди и красивые легенды',short='Архив без путаницы',image='falke-first',description='Основание, регистрация марки и смена владельца — разные события. Собираем хронологию аккуратно.',sections=[
 ('date','У одной компании бывает несколько начал',[
 'Мастерская, юридическое лицо, торговая марка и первая коллекция могут появиться в разные годы. Фраза «с такого-то года» нередко упрощает эту последовательность. Прежде чем поставить дату в справочник, стоит понять, что именно источник считает началом.',
 'FALKE даёт точную отправную точку: 8 мая 1895 года Франц Фальке-Роэн основал мастерскую в Шмалленберге. Официальная история описывает его работу кровельщиком и сезонную занятость в вязальном производстве. Это конкретный эпизод, который интереснее неподтверждённого рассказа о мгновенном рождении большой фабрики.']),
 ('people','Фотография возвращает истории человека',[
 'В архиве FALKE поколения семьи показаны рядом с этапами развития: 1928 год связан с Францем Фальке-младшим, 1951-й — с Паулем и Францем-Отто, 1990-й — со следующим поколением. Такая структура позволяет следить за преемственностью, не превращая страницу в длинный список несвязанных лет.',
 'При этом подпись должна соответствовать изображению. Архивный семейный портрет — не обязательно снимок, сделанный в год основания. Современная каталожная фотография рядом с 1977 годом может показать нынешний язык бренда, но её нельзя подписывать как рекламу 1977-го. В интерактивной хронологии ТОНКО эти различия указаны прямо.']),
 ('ownership','Отделяйте основание от приобретения',[
 'На странице OMSA в Golden Lady Company отмечен 1992 год вхождения в группу. Если перенести его в поле «основана», история станет неверной. Приобретения помогают объяснить развитие группы, но не отменяют более раннюю жизнь марки.',
 'Cecilia de Rafael связывает своё начало с Барселоной и 1977 годом. В текущем оформлении сайта уже используется юбилейная линия 1977–2027. На дату этой публикации, 15 ноября 2026 года, юбилейный дизайн не означает, что пятьдесят полных лет уже прошли. Даты в рекламной кампании и календарь публикации нужно сопоставлять.']),
 ('check','Как проверить красивый рассказ',[
 'Найдите исходную страницу, отметьте событие и выпишите, что именно она подтверждает. Для количественных заявлений полезно искать отчёт или отдельный документ. Для спорной легенды — независимый исторический источник. Официальный сайт надёжен как свидетельство того, что компания рассказывает о себе, но не является универсальным арбитром любых рекламных утверждений.',
 'История в ТОНКО остаётся открытой для уточнений. Хронология связывает выбранные события с первоисточниками, а карточки брендов показывают, какие даты проверены. Можно перейти от конкретного года к полному профилю и дальше — к материалам и современным фотографиям. Так архив становится маршрутом исследования, а не декоративным фоном.'])],sources=[('https://www.falke.com/uk_en/about-us/history/','FALKE: официальная хронология'),('https://ceciliaderafael.com/en/about','Cecilia de Rafael: основание и юбилейная подача'),('https://www.goldenladycompany.com/en/brand/omsa','Golden Lady Company: OMSA с 1992 года')],question='Современный снимок рядом с датой основания — это архивный кадр?',answers=['Да, если он на сайте бренда','Нет, нужна отдельная датировка','Да, если он чёрно-белый'],correct=1,feedback='Место размещения и обработка не устанавливают дату фотографии. Нужна подпись или другой проверяемый источник.',next=('history.html#brand-archive','Открыть хронологию'),related=['making','light'])
]

